	.string	"(t10,\002KINETIC ENERGY OF THE PARTICLE IS LESS OR EQUAL ZERO\002)"
	.align 32
	.type	fmt_10280.843,@object
	.size	fmt_10280.843,202
fmt_10280.843:
	.string	"(t10,\002EITHER YOUR RF-FREQENCY IS SHIFTED BY 180 DEGREES\002/,t10,\002THEN CHANGE THE SIGN OF <ITION> IN THE \002,\002<SYNCHROTRON>-INPUTBLOCK\002,/t10,\002OR YOUR ALFA-P IS WRONGLY \002,\002INTRODUCED IN THE SAME INPUTBLOCK\002)"
	.align 32
	.type	fmt_10290.844,@object
	.size	fmt_10290.844,49
fmt_10290.844:
	.string	"(t10,\002MULTIPOLECOEFFITIONS CANNOT BE SET EQUAL\002)"
	.align 32
	.type	fmt_10300.845,@object
	.size	fmt_10300.845,76
fmt_10300.845:
	.string	"(t10,\002THE RANDOM NUMBER: \002,i6,\002 FOR THE INITIAL\002,\002 STRUCTURE IS TOO SMALL\002)"
	.align 32
	.type	fmt_10310.846,@object
	.size	fmt_10310.846,56
fmt_10310.846:
	.string	"(t10,\002ELEMENTS THAT NEED RANDOM NUMBERS HAVE A KZ > 0\002)"
	.align 32
	.type	fmt_10320.847,@object
	.size	fmt_10320.847,73
fmt_10320.847:
	.string	"(t10,\002THERE ARE NOT ENOUGH RANDOM NUMBERS FOR THE INSERTED\002,\002 ELEMENTS\002)"
	.align 32
	.type	fmt_10330.848,@object
	.size	fmt_10330.848,143
fmt_10330.848:
	.string	"(t10,\002TO USE THE SAME RANDOMNUMBERS FOR 2 ELEMENTS, THE\002,\002 INSERTED ELEMENT MUST NOT NEED MORE OF SUCH NUMBERS THAN THE\002,\002 REFERENCE ELEMENT\002)"
	.align 32
	.type	fmt_10340.849,@object
	.size	fmt_10340.849,76
fmt_10340.849:
	.string	"(t10,\002NOT MORE THAN\002,i4,\002 OF EACH TYP OF INSERTED ELEMENTS\002,\002 CAN BE USED\002)"
	.align 32
	.type	fmt_10350.850,@object
	.size	fmt_10350.850,49
fmt_10350.850:
	.string	"(t10,\002PROBLEMS DURING MATRIX-INVERSION IN QMOD\002)"
	.align 32
	.type	fmt_10360.851,@object
	.size	fmt_10360.851,31
fmt_10360.851:
	.string	"(t10,\002NO CONVERGENCE IN RMOD\002)"
	.align 32
	.type	fmt_10370.852,@object
	.size	fmt_10370.852,58
fmt_10370.852:
	.string	"(t10,\002CHOSEN ORDERS OF RESONANCES CAN NOT BE CALCULATED\002)"
	.align 32
	.type	fmt_10380.853,@object
	.size	fmt_10380.853,49
fmt_10380.853:
	.string	"(t10,\002PROBLEMS DURING MATRIX-INVERSION IN RMOD\002)"
	.align 32
	.type	fmt_10390.854,@object
	.size	fmt_10390.854,126
fmt_10390.854:
	.string	"(t10,\002WITH THE SPECIFIED ELEMENTS THE RESONANCE CANNOT BE\002,\002 COMPENSATED - RESONANCEORDER AND ELEMENTTYP # MUST BE THE SAME\002)"
	.align 32
	.type	fmt_10400.855,@object
	.size	fmt_10400.855,49
fmt_10400.855:
	.string	"(t10,\002NOT MORE THAN 2 PARTICLES CAN BE TRACKED\002)"
	.align 32
	.type	fmt_10410.856,@object
	.size	fmt_10410.856,70
fmt_10410.856:
	.string	"(t10,\002GEOMETRY AND STRENGTH FILE (UNIT 2) IS EMPTY OR \002,\002 DISTROYED\002)"
	.align 32
	.type	fmt_10420.857,@object
	.size	fmt_10420.857,69
fmt_10420.857:
	.string	"(t10,\002TRACKING PARAMETER FILE (UNIT 3) IS EMPTY OR \002,\002 NONEXISTING\002)"
	.align 32
	.type	fmt_10430.858,@object
	.size	fmt_10430.858,56
fmt_10430.858:
	.string	"(t10,\002NOT MORE THAN \002,i4,\002 RANDOM NUMBERS CAN BE USED\002)"
	.align 32
	.type	fmt_10440.859,@object
	.size	fmt_10440.859,173
fmt_10440.859:
	.string	"(t10,\002FOR THE INPUTBLOCK - ORBIT CORRECTION - ONLY CORRE\002,\002CTORS WITH THE KEYWORDS ( HCOR= ; VCOR= )\002/t10,\002AND MONITORS WITH THE\002,\002 KEYWORDS ( HMON= ; VMON= ) ARE ALLOWED\002)"
	.align 32
	.type	fmt_10450.860,@object
	.size	fmt_10450.860,103
fmt_10450.860:
	.string	"(t10,\002FOR THE INPUTBLOCK - LINEAR OPTICS - ONLY\002,\002 THE KEYWORD ( ELEMENT ) AND ( BLOCK ) ARE ALLOWED\002)"
	.align 32
	.type	fmt_10460.861,@object
	.size	fmt_10460.861,59
fmt_10460.861:
	.string	"(t10,\002ORDER OF COMPENSATION CAN NOT BE LARGER THAN : \002,i4)"
	.align 32
	.type	fmt_10470.862,@object
	.size	fmt_10470.862,51
fmt_10470.862:
	.string	"(t10,\002ONLY UP TO 3 RESONANCES CAN BE COMPENSATED\002)"
	.align 32
	.type	fmt_10480.863,@object
	.size	fmt_10480.863,69
fmt_10480.863:
	.string	"(t10,\002RESONANCE TYPE IS OUT OF THE RANGE OF THE RESONANCE\002,\002 ORDER\002)"
	.align 32
	.type	fmt_10490.864,@object
	.size	fmt_10490.864,54
fmt_10490.864:
	.string	"(t10,\002ONLY UP TO 3 SUBRESONANCES CAN BE COMPENSATED\002)"
	.align 32
	.type	fmt_10500.865,@object
	.size	fmt_10500.865,95
fmt_10500.865:
	.string	"(t10,\002THE MULTIPOLE ORDER FOR THE SUBRESONANCE COMPENSATION\002,\002 SHOULD NOT EXCEED THE VALUE 9\002)"
	.align 32
	.type	fmt_10510.866,@object
	.size	fmt_10510.866,33
fmt_10510.866:
	.string	"(t10,\002TOO MANY RIPPLE ELEMENTS\002)"
	.align 32
	.type	fmt_10520.867,@object
	.size	fmt_10520.867,86
fmt_10520.867:
	.string	"(t10,\002MAXIMUM ORDER OF THE ONE TURN MAP IS \002,i4,/,\002 NEMA HAS TO BE LARGER THAN NORD\002)"
	.align 32
	.type	fmt_10530.868,@object
	.size	fmt_10530.868,94
fmt_10530.868:
	.string	"(t10,\002# OF VARIABLES -NV- OF THE ONE TURN MAP IS NOT\002,\002 IN THE ALLOWED RANGE [2 <= NV <= 5]\002)"
	.align 32
	.type	fmt_10540.869,@object
	.size	fmt_10540.869,64
fmt_10540.869:
	.string	"(t10,\002MAXIMUM NUMBER OF PARTICLES FOR VECTORIZATION\002,\002 IS \002,i4)"
	.align 32
	.type	fmt_10550.870,@object
	.size	fmt_10550.870,70
fmt_10550.870:
	.string	"(t10,\002MAXIMUM NUMBER OF DIFFERENT SEEDS FOR VECTORIZATION\002,\002 IS \002,i4)"
	.align 32
	.type	fmt_10560.871,@object
	.size	fmt_10560.871,79
fmt_10560.871:
	.string	"(t10,\002PROBLEMS WITH FILE 13 WITH INITIAL COORDINATES \002,\002 - ERROR CODE : \002,i10)"
	.align 32
	.type	fmt_10570.872,@object
	.size	fmt_10570.872,80
fmt_10570.872:
	.string	"(t10,\002PROBLEMS WITH FILE 2 WITH ACCELERATOR STRUCTURE \002,\002 - ERROR CODE : \002,i10)"
	.align 32
	.type	fmt_10580.873,@object
	.size	fmt_10580.873,78
fmt_10580.873:
	.string	"(t10,\002PROBLEMS WITH FILE 3 WITH TRACKING PARAMETERS \002,\002 - ERROR CODE : \002,i10)"
