	.type	fmt_10620.877,@object
	.size	fmt_10620.877,70
fmt_10620.877:
	.string	"(t10,\002ELEMENTS SPECIFIED FOR DECOUPLING ARE NOT\002,\002 SKEW QUADRUPOLES\002)"
	.align 32
	.type	fmt_10630.878,@object
	.size	fmt_10630.878,97
fmt_10630.878:
	.string	"(t10,\002THERE ARE THE APPROPRIATE ELEMENTS FOR\002,\002 THE DECOUPLING OR SIMULTANEOUS TUNE ADJUSTMENT\002)"
	.align 32
	.type	fmt_10640.879,@object
	.size	fmt_10640.879,51
fmt_10640.879:
	.string	"(t10,\002PROBLEMS DURING MATRIX-INVERSION IN DECOUP\002)"
	.align 32
	.type	fmt_10650.880,@object
	.size	fmt_10650.880,52
fmt_10650.880:
	.string	"(t10,\002MAXIMUM NUMBER OF EXTRA PARAMETERS IS : \002,i4)"
	.align 32
	.type	fmt_10660.881,@object
	.size	fmt_10660.881,52
fmt_10660.881:
	.string	"(t10,\002EXTRA PARAMETERS FOR THE MAP DOES NOT EXIST\002)"
	.align 32
	.type	fmt_10670.882,@object
	.size	fmt_10670.882,62
fmt_10670.882:
	.string	"(t10,\002ONLY SINGLE KICK ELEMENTS ALLOWED FOR MAP CALCULATION\002)"
	.align 32
	.type	fmt_10680.883,@object
	.size	fmt_10680.883,95
fmt_10680.883:
	.string	"(t10,\002THE ORDER OF THE NORMAL FORM IS TOO HIGH. CHECK THE\002,\002 DIFFERENTIAL ALGEBRA PARAMETERS\002)"
	.align 32
	.type	fmt_10690.884,@object
	.size	fmt_10690.884,83
fmt_10690.884:
	.string	"(t10,\002TOO MANY VARIABLES SPECIFIED. CHECK THE DIFFERENTIAL\002,\002 ALGEBRA PARAMETERS\002)"
	.align 32
	.type	fmt_10700.885,@object
	.size	fmt_10700.885,32
fmt_10700.885:
	.string	"(t10,\002NO CORRECTORS SPECIFIED\002)"
	.align 32
	.type	fmt_10710.886,@object
	.size	fmt_10710.886,52
